"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["47945"],{30777(e){e.exports=JSON.parse('{"id":"FIN-468","slug":"copyright","term":"Copyright","also_known_as":[],"difficulty":"Beginner","definition":"Copyright is a legal right that protects original creative works, such as books, music, films, artwork, photographs and software, giving the creator exclusive rights to copy, distribute and adapt them.","explanation":["Copyright usually arises automatically when an original work is created and fixed in a tangible form, such as written down or recorded. In many countries, no registration is needed, although registration can help in legal disputes.","Copyright protects the expression of ideas, not the ideas themselves. Anyone can write a story about a detective solving a murder, but they cannot copy the exact text of someone else\'s detective novel.","Copyright lasts a long time. In many countries, it lasts for the life of the author plus 70 years, although rules vary by country and type of work. After it expires, the work enters the public domain and can be used freely.","For example, a songwriter owns the copyright in their song and earns royalties when it is played on the radio, streamed or used in a film.","Copyright allows creators and companies to earn money from their work through sales, licensing and royalties. Laws also allow certain limited uses without permission, such as quotation for criticism or education, under rules known as fair use or fair dealing, depending on the country."],"note":"","total":1725,"prev":{"slug":"copayment","term":"Copayment"},"next":{"slug":"core-inflation","term":"Core Inflation"}}')}}]);